function normalize(s){return s.normalize('NFKC').toLocaleLowerCase().replace(/[^\p{L}\p{N}]+/gu,'')}
function distance(a,b){let x=Array.from(a),y=Array.from(b);if(Math.abs(x.length-y.length)>1)return 99;let d=Array.from({length:y.length+1},(_,i)=>i);for(let i=1;i<=x.length;i++){let p=d[0];d[0]=i;for(let j=1;j<=y.length;j++){let q=d[j];d[j]=Math.min(d[j]+1,d[j-1]+1,p+(x[i-1]===y[j-1]?0:1));p=q}}return d[y.length]}
function likeness(a,b){if(!a||!b)return 0;if(a===b)return 1;if(Math.min(a.length,b.length)<5)return 0;return distance(a,b)===1?.82:0}
function near(a,b,dir){let x=a.bbox,y=b.bbox,ah=x.y1-x.y0,bh=y.y1-y.y0,h=Math.max(ah,bh,8),dy=(y.y0+y.y1-x.y0-x.y1)/2,dx=(y.x0+y.x1-x.x0-x.x1)/2;if(Math.abs(dy)<h*.8&&dx*dir>0&&Math.abs(dx)<h*24)return 1-Math.min(.6,Math.abs(dx)/(h*40));if(dy*dir>h*.5&&Math.abs(dy)<h*4&&Math.abs(dx)<h*18)return .58;return 0}
export function matchText(text,data){let sources=[];for(const [lineNo,line] of text.split(/\r?\n/).entries()){let tokens=(line.match(/\S+/gu)||[]).filter(t=>normalize(t));tokens.forEach((t,wordNo)=>sources.push({text:t,n:normalize(t),lineNo,wordNo}))}let ts=[];for(const b of data.blocks||[])for(const p of b.paragraphs||[])for(const l of p.lines||[])for(const w of l.words||[]){let n=normalize(w.text);if(n&&w.bbox&&w.confidence>=25)ts.push({...w,n,index:ts.length})}
let entries=sources.map((s,i)=>{let c=[];for(const w of ts){let sim=likeness(s.n,w.n);if(!sim)continue;let score=sim*2+Math.min(1,w.confidence/100)*.2,context=0;for(let k=-3;k<=3;k++){if(!k)continue;let other=sources[i+k];if(!other||other.lineNo!==s.lineNo)continue;let best=0;for(const v of ts){let sm=likeness(other.n,v.n);if(sm)best=Math.max(best,sm*near(w,v,Math.sign(k)))}context+=best/(Math.abs(k));}score+=context; c.push({w,score,sim,context})}c.sort((a,b)=>b.score-a.score);return {source:s,candidates:c}});
// Prefer strong, unambiguous matches; never reuse a detected box.
entries.sort((a,b)=>{let score=e=>e.candidates.length?(e.candidates[0].score+(e.candidates.length===1?1:Math.min(1,e.candidates[0].score-e.candidates[1].score))):-1;return score(b)-score(a)});let used=new Set(),matches=[];for(const e of entries){let choices=e.candidates.filter(c=>!used.has(c.w.index));if(!choices.length)continue;let best=choices[0],next=choices[1];if(best.sim<1&&best.context<.35)continue;if(next&&best.score-next.score<.22)continue;if(e.source.n.length<3&&best.context<.5)continue;used.add(best.w.index);matches.push({text:e.source.text,bbox:best.w.bbox,confidence:best.w.confidence,match:best.sim,context:best.context,sourceLine:e.source.lineNo,wordNo:e.source.wordNo,detected:best.w.text})}matches.sort((a,b)=>a.sourceLine-b.sourceLine||a.wordNo-b.wordNo);return{matches,sourceCount:sources.length,detectedCount:ts.length}}
